', 'tool', '{"label": "DOC", "curves": [{"name": "std_curve", "label": "Standard curve (DOC corr)", "required": false, "description": "Applied to every replicate before averaging: corrected = slope * measured + intercept."}], "params": [{"kind": "replicates", "name": "DOC", "when": null, "curve": "std_curve", "label": "DOC", "units": "ppb", "default": null, "section": "lab", "required": false, "suggested": 3, "description": "One value per analyser vial, in run order. Add or remove vials as measured; a blank vial is a gap, never a shift.", "parameter_code": "DOC_ppb"}], "outputs": [{"key": "DOC_avg_ppb", "label": "DOC average", "units": "ppb", "aggregate": "mean", "aggregate_of": "DOC", "per_replicate": false, "suggested_parameter_code": null}, {"key": "DOC_sd_ppb", "label": "DOC standard deviation", "units": "ppb", "aggregate": "sd", "aggregate_of": "DOC", "per_replicate": false, "suggested_parameter_code": null}], "sections": [{"key": "lab", "label": "Lab measurements"}], "constants": [], "description": "Dissolved organic carbon: the analyser replicates are stored as readings, corrected through the chosen standard curve, and their mean and standard deviation are the served DOC.", "match_keywords": ["doc", "organic carbon", "dissolved organic"]}', '{"cases": [{"name": "rust_pin_with_curve", "absent": [], "curves": {"std_curve": {"slope": 1.05, "intercept": -2.0}}, "inputs": {"DOC": [120.0, 125.0, 118.0]}, "expected": {"DOC_sd_ppb": 3.78582883923719, "DOC_avg_ppb": 125.05}, "constants": {}}, {"name": "golden_no_curve", "absent": [], "curves": {}, "inputs": {"DOC": [120.0, 125.0, 118.0]}, "expected": {"DOC_sd_ppb": 3.60555127546399, "DOC_avg_ppb": 121.0}, "constants": {}}, {"name": "single_replicate_omits_sd", "absent": ["DOC_sd_ppb"], "curves": {}, "inputs": {"DOC": [120.0]}, "expected": {"DOC_avg_ppb": 120.0}, "constants": {}}, {"name": "lone_second_replicate_stays_on_its_own_number", "absent": ["DOC_sd_ppb"], "curves": {}, "inputs": {"DOC": [null, 120.0]}, "expected": {"DOC_avg_ppb": 120.0}, "constants": {}}, {"name": "all_null_omits_both", "absent": ["DOC_avg_ppb", "DOC_sd_ppb"], "curves": {}, "inputs": {"DOC": [null, null, null]}, "expected": {}, "constants": {}}, {"name": "one_null_no_curve", "absent": [], "curves": {}, "inputs": {"DOC": [120.0, null, 118.0]}, "expected": {"DOC_sd_ppb": 1.4142135623731, "DOC_avg_ppb": 119.0}, "constants": {}}, {"name": "golden_avg_rand_1", "absent": [], "curves": {"std_curve": {"slope": 0.961278225202113, "intercept": -0.97404258325696}}, "inputs": {"DOC": [190.671224833932, 245.170278369915, 230.796007509343]}, "expected": {"DOC_sd_ppb": 27.1515432188154, "DOC_avg_ppb": 212.633998467253}, "constants": {}}, {"name": "golden_avg_rand_9_null_with_curve", "absent": [], "curves": {"std_curve": {"slope": 1.10074498825707, "intercept": 2.28358845226467}}, "inputs": {"DOC": [null, 467.760288110003, 472.654093289748]}, "expected": {"DOC_sd_ppb": 3.8090651005153, "DOC_avg_ppb": 519.861797057587}, "constants": {}}, {"name": "golden_sd_rand_1_with_curve", "absent": [], "curves": {"std_curve": {"slope": 0.932979776454158, "intercept": -3.29249400179833}}, "inputs": {"DOC": [108.206150960177, 429.328132607043, 410.717265773565]}, "expected": {"DOC_sd_ppb": 168.186120201977, "DOC_avg_ppb": 291.60734550696}, "constants": {}}, {"name": "golden_sd_rand_2_no_curve", "absent": [], "curves": {}, "inputs": {"DOC": [74.2234499659389, 429.851801227778, 476.666156097781]}, "expected": {"DOC_sd_ppb": 220.084544270995, "DOC_avg_ppb": 326.913802430499}, "constants": {}}, {"name": "no_replicates_omits_both", "absent": ["DOC_avg_ppb", "DOC_sd_ppb"], "curves": {}, "inputs": {}, "expected": {}, "constants": {}}, {"name": "two_replicates_third_absent", "absent": [], "curves": {"std_curve": {"slope": 1.01862098516431, "intercept": -4.9273814773187}}, "inputs": {"DOC": [271.935691975523, 399.443094816525]}, "expected": {"DOC_sd_ppb": 91.8402423462114, "DOC_avg_ppb": 337.012879132948}, "constants": {}}, {"name": "five_replicates", "absent": [], "curves": {}, "inputs": {"DOC": [120.0, 125.0, 118.0, 122.5, 119.75]}, "expected": {"DOC_sd_ppb": 2.7294688127912363, "DOC_avg_ppb": 121.05}, "constants": {}}, {"name": "five_replicates_with_curve", "absent": [], "curves": {"std_curve": {"slope": 1.05, "intercept": -2.0}}, "inputs": {"DOC": [120.0, 125.0, 118.0, 122.5, 119.75]}, "expected": {"DOC_sd_ppb": 2.865942253430795, "DOC_avg_ppb": 125.1025}, "constants": {}}, {"name": "ten_replicates", "absent": [], "curves": {}, "inputs": {"DOC": [101.0, 102.5, 99.0, 100.25, 103.0, 98.5, 101.75, 100.0, 102.0, 99.5]}, "expected": {"DOC_sd_ppb": 1.536590742882148, "DOC_avg_ppb": 100.75}, "constants": {}}, {"name": "no_replicates_at_all", "absent": ["DOC_avg_ppb", "DOC_sd_ppb"], "curves": {}, "inputs": {}, "expected": {}, "constants": {}}, {"name": "empty_list_is_no_replicates", "absent": ["DOC_avg_ppb", "DOC_sd_ppb"], "curves": {}, "inputs": {"DOC": []}, "expected": {}, "constants": {}}], "notes": "No portal-vs-Rust divergence for this tool: both average the curve-corrected replicates and take their sd (na.rm). The three replicates are declared as the portal''s own columns DOC_rep_1/2/3 and read by name, so a replicate entered alone keeps its number (lone_second_replicate_stays_on_its_own_number); an absent replicate is NA in the row the portal builds. A lone replicate yields an average and no sd: calcSd returns the ''KEEP OLD'' sentinel, which carries the stored value forward in the portal, and this tool is stateless, so the key is omitted. The sentinel is the only omission; no plausibility filter is applied, so a NaN or Inf would be emitted as the portal displays it. calcMean and calcSd over finite replicates reach neither, so no case pins one. Inputs reshaped to the replicates vector; expected values unchanged. The five-, ten- and empty-replicate cases pin the width generalisation.", "tolerance": 0.000000001}', 'sha256:1d683aadb6114d3ea36c336e78d9291fa6929a66d3249398d5bf0f43eee7ba74', 'seed', '2026-09-04 12:10:27.924083+00', '2026-09-04 12:10:27.924083+00', NULL) ON CONFLICT DO NOTHING;

